import z3
from itertools import combinations

n = 21
edges = {}
for i in range(n):
    for j in range(i+1, n):
        edges[(i,j)] = z3.Bool(f"e_{i}_{j}")

solver = z3.Solver()

for quad in combinations(range(n), 4):
    solver.add(z3.Or([edges[(i,j)] for i,j in combinations(quad, 2)]))

for quint in combinations(range(n), 5):
    solver.add(z3.Not(z3.And([edges[(i,j)] for i,j in combinations(quint, 2)])))

result = solver.check()
print(f"Result: {result}")

if result == z3.sat:
    model = solver.model()
    # Extract solution in lexicographic order
    solution = []
    for i in range(n):
        for j in range(i+1, n):
            val = model.eval(edges[(i,j)])
            solution.append(1 if val else 0)
    print(f"Solution length: {len(solution)}")
    print(f"First 20: {solution[:20]}")
    print(f"Sum (number of blue edges): {sum(solution)}")

    # Verify
    # Check no red K_4
    ok = True
    for quad in combinations(range(n), 4):
        idxs = [(i,j) for i,j in combinations(quad, 2)]
        vals = [model.eval(edges[(i,j)]) for i,j in combinations(quad, 2)]
        if all(not v for v in vals):
            print(f"Found red K_4: {quad}")
            ok = False
            break
    if ok:
        print("No red K_4: OK")

    # Check no blue K_5
    for quint in combinations(range(n), 5):
        vals = [model.eval(edges[(i,j)]) for i,j in combinations(quint, 2)]
        if all(v for v in vals):
            print(f"Found blue K_5: {quint}")
            ok = False
            break
    if ok:
        print("No blue K_5: OK")
